1	// Room bookings page script. Classic script: runs its setup at once.
2	(function () {
3	  'use strict';
4	
5	  const NO_REPLY = 'Could not reach the server.';
6	  const REQUEST_FAILED = 'Request failed.';
7	
8	  const form = document.getElementById('booking-form');
9	  const roomSelect = document.getElementById('room');
10	  const titleInput = document.getElementById('title');
11	  const dateInput = document.getElementById('date');
12	  const startInput = document.getElementById('start');
13	  const endInput = document.getElementById('end');
14	  const bookButton = document.getElementById('book');
15	  const filterInput = document.getElementById('filter-date');
16	  const showAllButton = document.getElementById('show-all');
17	  const list = document.getElementById('booking-list');
18	  const errorBox = document.getElementById('error');
19	
20	  let listSequence = 0;
21	
22	  // Resolves to { status, body } or to null when there is no usable reply.
23	  // A 204 body is never read; any other body must parse as JSON.
24	  async function request(url, options) {
25	    try {
26	      const res = await fetch(url, options);
27	      const status = res.status;
28	      if (status === 204) {
29	        return { status, body: undefined };
30	      }
31	      const body = await res.json();
32	      return { status, body };
33	    } catch {
34	      // Network failure or unreadable body: both count as no reply.
35	      return null;
36	    }
37	  }
38	
39	  function isPlainObject(value) {
40	    return typeof value === 'object' && value !== null && !Array.isArray(value);
41	  }
42	
43	  function errorMessage(body) {
44	    if (isPlainObject(body) && typeof body.error === 'string') {
45	      return body.error;
46	    }
47	    return REQUEST_FAILED;
48	  }
49	
50	  function showError(text) {
51	    errorBox.textContent = text;
52	  }
53	
54	  function bookingText(booking) {
55	    return booking.date + ' ' + booking.start + '-' + booking.end + ' ' +
56	      booking.room + ': ' + booking.title;
57	  }
58	
59	  function bookingItem(booking) {
60	    const item = document.createElement('li');
61	    const cancel = document.createElement('button');
62	    cancel.type = 'button';
63	    cancel.textContent = 'Cancel';
64	    cancel.addEventListener('click', function () {
65	      cancelBooking(booking.id, cancel);
66	    });
67	    item.append(bookingText(booking), cancel);
68	    return item;
69	  }
70	
71	  function emptyItem() {
72	    const item = document.createElement('li');
73	    item.append('No bookings.');
74	    return item;
75	  }
76	
77	  function renderBookings(bookings) {
78	    const items = bookings.length === 0 ? [emptyItem()] : bookings.map(bookingItem);
79	    list.replaceChildren(...items);
80	  }
81	
82	  function listUrl() {
83	    const date = filterInput.value;
84	    return date === '' ? '/api/bookings' : '/api/bookings?date=' + date;
85	  }
86	
87	  // Only the outcome of the last list fetch started is used.
88	  async function loadList() {
89	    listSequence += 1;
90	    const sequence = listSequence;
91	    const reply = await request(listUrl(), { method: 'GET' });
92	    if (sequence !== listSequence) {
93	      return;
94	    }
95	    if (reply === null) {
96	      showError(NO_REPLY);
97	      return;
98	    }
99	    if (reply.status !== 200) {
100	      showError(errorMessage(reply.body));
101	      return;
102	    }
103	    const bookings = isPlainObject(reply.body) ? reply.body.bookings : undefined;
104	    if (!Array.isArray(bookings)) {
105	      showError(REQUEST_FAILED);
106	      return;
107	    }
108	    renderBookings(bookings);
109	  }
110	
111	  async function loadRooms() {
112	    const reply = await request('/api/rooms', { method: 'GET' });
113	    if (reply === null) {
114	      showError(NO_REPLY);
115	      return;
116	    }
117	    if (reply.status !== 200) {
118	      showError(errorMessage(reply.body));
119	      return;
120	    }
121	    const rooms = isPlainObject(reply.body) ? reply.body.rooms : undefined;
122	    if (!Array.isArray(rooms)) {
123	      showError(REQUEST_FAILED);
124	      return;
125	    }
126	    const options = rooms.map(function (name) {
127	      const option = document.createElement('option');
128	      option.value = name;
129	      option.textContent = name;
130	      return option;
131	    });
132	    roomSelect.append(...options);
133	  }
134	
135	  async function submitBooking(event) {
136	    event.preventDefault();
137	    if (bookButton.disabled) {
138	      return;
139	    }
140	    bookButton.disabled = true;
141	    const payload = {
142	      room: roomSelect.value,
143	      title: titleInput.value,
144	      date: dateInput.value,
145	      start: startInput.value,
146	      end: endInput.value,
147	    };
148	    const reply = await request('/api/bookings', {
149	      method: 'POST',
150	      headers: { 'Content-Type': 'application/json' },
151	      body: JSON.stringify(payload),
152	    });
153	    bookButton.disabled = false;
154	    if (reply === null) {
155	      showError(NO_REPLY);
156	      return;
157	    }
158	    if (reply.status !== 201) {
159	      showError(errorMessage(reply.body));
160	      return;
161	    }
162	    titleInput.value = '';
163	    showError('');
164	    loadList();
165	  }
166	
167	  async function cancelBooking(id, button) {
168	    if (button.disabled) {
169	      return;
170	    }
171	    button.disabled = true;
172	    const reply = await request('/api/bookings/' + id, { method: 'DELETE' });
173	    button.disabled = false;
174	    if (reply === null) {
175	      showError(NO_REPLY);
176	      return;
177	    }
178	    showError(reply.status === 204 ? '' : errorMessage(reply.body));
179	    loadList();
180	  }
181	
182	  form.addEventListener('submit', submitBooking);
183	  filterInput.addEventListener('change', function () {
184	    loadList();
185	  });
186	  showAllButton.addEventListener('click', function () {
187	    filterInput.value = '';
188	    loadList();
189	  });
190	
191	  loadRooms();
192	  loadList();
193	})();
